import React, { useState, useEffect } from "react";
import { Rating, CircularProgress, Box, Typography, Card, CardContent, Avatar } from "@mui/material";
import Masonry from "@mui/lab/Masonry";

const Testimonial = () => {
  const [testimonials, setTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageLoadErrors, setImageLoadErrors] = useState(new Set());

  const GOOGLE_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbyhfwASOAR05ljOLJfhk2hX10qYh_MVMXworB9L0GXu7M3q1BTvnRL5aD2PcXq98Xjk/exec";

  // Function to convert Google Drive file URL to direct image URL
  const convertDriveUrlToDirect = (driveUrl) => {
    if (!driveUrl) return null;
    
    try {
      // If it's already a direct image URL, return as is
      if (driveUrl.includes('drive.google.com/uc?')) {
        return driveUrl;
      }
      
      let fileId = '';
      
      // Format: https://drive.google.com/file/d/1p0vmnLs-JoJ4guWDmJcHwAIUXNuOsxyf/view?usp=drivesdk
      if (driveUrl.includes('/file/d/')) {
        const parts = driveUrl.split('/file/d/')[1]?.split('/');
        if (parts && parts.length > 0) {
          fileId = parts[0];
        }
      }
      // Format: https://drive.google.com/open?id=1p0vmnLs-JoJ4guWDmJcHwAIUXNuOsxyf
      else if (driveUrl.includes('id=')) {
        fileId = driveUrl.split('id=')[1]?.split('&')[0];
      }
      // If it's already a direct URL or just a file ID
      else {
        fileId = driveUrl;
      }
      
      // Clean up file ID (remove any special characters)
      fileId = fileId.replace(/[^a-zA-Z0-9_-]/g, '');
      
      if (fileId && fileId.length > 10) {
        return `https://drive.google.com/uc?export=view&id=${fileId}`;
      }
      
      return null;
    } catch (error) {
      console.error('Error converting Drive URL:', error);
      return null;
    }
  };

  const fetchTestimonials = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch(`${GOOGLE_SCRIPT_URL}?action=getTestimonials`);
      if (!response.ok) throw new Error(`Failed to fetch testimonials: ${response.status}`);
      const data = await response.json();
      
      if (data.success && data.testimonials) {
        console.log('Raw testimonials data:', data.testimonials);
        
        // Process testimonials to convert Drive URLs to direct image URLs
        const processedTestimonials = data.testimonials.map(testimonial => {
          const processedPhoto = testimonial.photo ? convertDriveUrlToDirect(testimonial.photo) : null;
          
          console.log('Photo conversion:', {
            original: testimonial.photo,
            converted: processedPhoto,
            name: testimonial.name
          });
          
          return {
            ...testimonial,
            photo: processedPhoto,
            // Process additional photos if they exist
            additionalPhotos: testimonial.additionalPhotos ? 
              testimonial.additionalPhotos.map(photo => convertDriveUrlToDirect(photo)).filter(Boolean) : []
          };
        }).filter(testimonial => testimonial !== null);
        
        setTestimonials(processedTestimonials);
        console.log('Processed testimonials:', processedTestimonials);
      } else {
        throw new Error(data.message || "No testimonials found");
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setError(err.message);
      setTestimonials([]);
    } finally {
      setLoading(false);
    }
  };

  const handleImageError = (testimonialId, photoType = 'main') => {
    setImageLoadErrors(prev => new Set(prev).add(`${testimonialId}-${photoType}`));
  };

  const isImageErrored = (testimonialId, photoType = 'main') => {
    return imageLoadErrors.has(`${testimonialId}-${photoType}`);
  };

  useEffect(() => {
    fetchTestimonials();
  }, []);

  if (loading) {
    return (
      <Box sx={{ display: "flex", justifyContent: "center", alignItems: "center", minHeight: 400, background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)", color: "white" }}>
        <Box sx={{ textAlign: "center" }}>
          <CircularProgress sx={{ color: "#FF9800", mb: 2 }} />
          <Typography variant="h6">Loading testimonials...</Typography>
        </Box>
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ textAlign: "center", minHeight: 400, background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)", color: "white", padding: 4 }}>
        <Typography variant="h4" color="error" gutterBottom>Error Loading Testimonials</Typography>
        <Typography variant="body1">{error}</Typography>
        <button 
          onClick={fetchTestimonials} 
          style={{ 
            background: "#FF9800", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: 5, 
            cursor: "pointer",
            marginTop: 10
          }}
        >
          Try Again
        </button>
      </Box>
    );
  }

  return (
    <Box
      id="testimonials"
      sx={{
        background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        color: "white",
        p: { xs: 3, md: 6 },
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        textAlign: "center",
        minHeight: "100vh"
      }}
    >
      <Typography
        variant="h2"
        component="h1"
        sx={{
          mb: 5,
          fontFamily: "'AlanSans', sans-serif",
          fontWeight: 700,
          background: "linear-gradient(45deg, #FF9800 30%, #FF5722 90%)",
          backgroundClip: "text",
          WebkitBackgroundClip: "text",
          color: "transparent",
          fontSize: { xs: '2rem', md: '3rem' }
        }}
      >
        What They've Said
      </Typography>

      <Box sx={{ width: "100%", maxWidth: 1200 }}>
        <Masonry columns={{ xs: 1, sm: 2, md: 3 }} spacing={3}>
          {testimonials.map((testimonial, index) => {
            const hasPhoto = testimonial.photo && !isImageErrored(index, 'main');
            const displayName = testimonial.name || 'Anonymous';
            
            return (
              <Card
                key={index}
                sx={{
                  background: "rgba(255,255,255,0.05)",
                  backdropFilter: "blur(10px)",
                  border: "1px solid rgba(255,255,255,0.1)",
                  borderRadius: 2,
                  overflow: "hidden",
                  transition: "transform 0.3s ease, box-shadow 0.3s ease",
                  "&:hover": {
                    transform: "translateY(-5px)",
                    boxShadow: "0 10px 30px rgba(255,152,0,0.2)"
                  }
                }}
              >
                <CardContent sx={{ p: 3, display: "flex", flexDirection: "column" }}>
                  {/* Photo and Name Section */}
                  <Box sx={{ display: "flex", alignItems: "flex-start", mb: 2 }}>
                    <Avatar
                      src={hasPhoto ? testimonial.photo : undefined}
                      alt={displayName}
                      onError={() => handleImageError(index, 'main')}
                      sx={{
                        width: 60,
                        height: 60,
                        mr: 2,
                        border: "2px solid #FF9800",
                        bgcolor: hasPhoto ? 'transparent' : 'rgba(255,152,0,0.3)',
                        fontSize: '1.5rem',
                        fontWeight: 'bold'
                      }}
                    >
                      {!hasPhoto && displayName.charAt(0).toUpperCase()}
                    </Avatar>
                    
                    <Box sx={{ flex: 1, textAlign: 'left' }}>
                      <Typography 
                        variant="h6" 
                        sx={{ 
                          color: "#FFFFFF", 
                          fontWeight: 600, 
                          fontFamily: "'AlanSans', sans-serif",
                          mb: 0.5
                        }}
                      >
                        {displayName}
                      </Typography>
                      
                      <Rating
                        value={testimonial.rating || 0}
                        readOnly
                        size="small"
                        sx={{ 
                          color: "#FF9800", 
                          "& .MuiRating-iconFilled": { color: "#FF9800" },
                          "& .MuiRating-iconEmpty": { color: "rgba(255,255,255,0.3)" }
                        }}
                      />
                      
                      <Typography 
                        variant="caption" 
                        sx={{ 
                          color: "rgba(255,255,255,0.6)", 
                          display: "block", 
                          mt: 0.5 
                        }}
                      >
                        {testimonial.timestamp ? 
                          new Date(testimonial.timestamp).toLocaleDateString('en-US', {
                            year: 'numeric',
                            month: 'long',
                            day: 'numeric'
                          }) : 
                          'Recent'
                        }
                      </Typography>
                    </Box>
                  </Box>

                  {/* Comment Section */}
                  <Typography
                    variant="body1"
                    sx={{
                      color: "rgba(255,255,255,0.9)",
                      fontStyle: "italic",
                      lineHeight: 1.6,
                      position: "relative",
                      pl: 3,
                      "&:before": {
                        content: '"“"',
                        fontSize: "3rem",
                        color: "#FF9800",
                        opacity: 0.7,
                        position: "absolute",
                        top: -10,
                        left: 0,
                        lineHeight: 1,
                      },
                      "&:after": {
                        content: '"”"',
                        fontSize: "3rem",
                        color: "#FF9800",
                        opacity: 0.7,
                        position: "absolute",
                        bottom: -20,
                        right: 0,
                        lineHeight: 1,
                      }
                    }}
                  >
                    {testimonial.comment || "No comment provided."}
                  </Typography>

                  {/* Additional Photos Section */}
                  {testimonial.additionalPhotos && testimonial.additionalPhotos.length > 0 && (
                    <Box sx={{ mt: 2, pt: 2, borderTop: "1px solid rgba(255,255,255,0.1)" }}>
                      <Typography 
                        variant="caption" 
                        sx={{ 
                          color: "rgba(255,255,255,0.6)", 
                          display: "block", 
                          mb: 1 
                        }}
                      >
                        Additional photos:
                      </Typography>
                      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                        {testimonial.additionalPhotos.slice(0, 4).map((photo, photoIndex) => (
                          <Avatar
                            key={photoIndex}
                            src={isImageErrored(index, `additional-${photoIndex}`) ? null : photo}
                            onError={() => handleImageError(index, `additional-${photoIndex}`)}
                            sx={{
                              width: 40,
                              height: 40,
                              border: "1px solid rgba(255,255,255,0.2)",
                              cursor: 'pointer',
                              bgcolor: 'rgba(255,255,255,0.1)',
                              '&:hover': {
                                transform: 'scale(1.1)',
                                transition: 'transform 0.2s',
                                borderColor: '#FF9800'
                              }
                            }}
                            onClick={() => window.open(photo, '_blank')}
                          />
                        ))}
                        {testimonial.additionalPhotos.length > 4 && (
                          <Avatar
                            sx={{
                              width: 40,
                              height: 40,
                              bgcolor: 'rgba(255,152,0,0.3)',
                              color: '#FF9800',
                              fontSize: '0.8rem',
                              fontWeight: 'bold',
                              cursor: 'pointer'
                            }}
                            onClick={() => {
                              testimonial.additionalPhotos.forEach(photo => window.open(photo, '_blank'));
                            }}
                          >
                            +{testimonial.additionalPhotos.length - 4}
                          </Avatar>
                        )}
                      </Box>
                    </Box>
                  )}

                  {/* Debug info - remove in production */}
                  {process.env.NODE_ENV === 'development' && (
                    <Box sx={{ mt: 1, p: 1, bgcolor: 'rgba(0,0,0,0.3)', borderRadius: 1 }}>
                      <Typography variant="caption" sx={{ color: 'rgba(255,255,255,0.5)', fontSize: '0.7rem' }}>
                        Photo: {testimonial.photo ? 'Available' : 'Not available'}
                      </Typography>
                    </Box>
                  )}
                </CardContent>
              </Card>
            );
          })}
        </Masonry>
      </Box>

      {testimonials.length === 0 && !loading && (
        <Box sx={{ textAlign: "center", mt: 4 }}>
          <Typography variant="h5" sx={{ color: "rgba(255,255,255,0.7)", mb: 2 }}>
            No testimonials yet.
          </Typography>
          <Typography variant="body1" sx={{ color: "rgba(255,255,255,0.5)" }}>
            Be the first to share your experience!
          </Typography>
        </Box>
      )}
    </Box>
  );
};

export default Testimonial;
